@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@Import(MultimodalDiscoveryIntegrationTest.TimeConfig.class)
@Testcontainers class MultimodalDiscoveryIntegrationTest{
 static TestIssuer issuer=new TestIssuer();@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("travbook.oidc-issuer",issuer::url);r.add("travbook.local-identity",()->true);}
 @TestConfiguration static class TimeConfig{@Bean @Primary MutableClock testClock(){return new MutableClock();}}static class MutableClock extends Clock{Instant now=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return Clock.fixed(now,zone);}public Instant instant(){return now;}}
 @Autowired DiscoverBuses buses;@Autowired DiscoverCabs cabs;@Autowired ExploreHolidays holidays;@Autowired Customers customers;@Autowired MutableClock clock;@Autowired JdbcClient jdbc;@Autowired ObjectMapper json;@LocalServerPort int port;CustomerIdentity identity;String token;HttpClient http=HttpClient.newHttpClient();
 @BeforeEach void reset()throws Exception{clock.now=Instant.now();identity=new CustomerIdentity(issuer.url(),"multi-"+UUID.randomUUID());customers.resolve(identity);token=issuer.token(identity.subject(),"bookings:read bookings:write");}@AfterAll static void close(){issuer.close();}
 String key(){return UUID.randomUUID().toString();}LocalDate future(){return LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(10);}
 HttpResponse<String> call(String method,String path,String auth,String key,Object body)throws Exception{var request=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).timeout(Duration.ofSeconds(10));if(auth!=null)request.header("Authorization","Bearer "+auth);if(key!=null)request.header("Idempotency-Key",key);if(method.equals("POST"))request.header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else request.GET();return http.send(request.build(),HttpResponse.BodyHandlers.ofString());}
 @Test void busSearchSeatPricesRestrictionsPointsAndExpiryAreAuthoritative()throws Exception{var criteria=new Bus.Criteria(Bus.City.DELHI,Bus.City.JAIPUR,future(),List.of(30,10));var page=buses.search(criteria);assertThat(page.total()).isEqualTo(4);var trip=page.items().stream().filter(t->t.type()==Bus.Type.SLEEPER).findFirst().orElseThrow();assertThat(trip.seats()).anyMatch(s->s.deck()==Bus.Deck.UPPER);String board=trip.boarding().getFirst().id(),drop=trip.dropping().getFirst().id();assertThatThrownBy(()->buses.reprice(page.id(),trip.id(),List.of("L1","U1"),board,drop)).isInstanceOf(DomainFailure.class).hasMessageContaining("minimum age");var checked=buses.reprice(page.id(),trip.id(),List.of("L1","L2"),board,drop);assertThat(checked.changed()).isTrue();assertThat(checked.complete()).isTrue();assertThat(checked.total().decimal()).isEqualByComparingTo(checked.previousTotal().decimal().add(new BigDecimal("50")));assertThatThrownBy(()->buses.reprice(page.id(),trip.id(),List.of("L1","L1"),board,drop)).isInstanceOf(DomainFailure.class);assertThatThrownBy(()->buses.reprice(page.id(),trip.id(),List.of("L4"),board,drop)).isInstanceOf(DomainFailure.class).hasMessageContaining("restricted");assertThatThrownBy(()->buses.reprice(page.id(),trip.id(),List.of("L1"),"other",drop)).isInstanceOf(DomainFailure.class);assertThat(buses.trip(page.id(),trip.id(),false).criteria()).isEqualTo(criteria);clock.now=page.expiresAt();assertThatThrownBy(()->buses.page(page.id(),Bus.Filter.defaults())).isInstanceOf(DomainFailure.class).hasMessageContaining("expired");}
 @Test void busContentionAndPartialFailureDifferFromEmptyResults(){var page=buses.search(new Bus.Criteria(Bus.City.DELHI,Bus.City.AGRA,future(),List.of(30)));assertThat(page.coverage()).anyMatch(c->c.status()==SupplierCoverage.Status.UNAVAILABLE);var trip=page.items().stream().filter(t->t.type()==Bus.Type.SEATER).findFirst().orElseThrow();assertThatThrownBy(()->buses.reprice(page.id(),trip.id(),List.of("L6"),trip.boarding().getFirst().id(),trip.dropping().getFirst().id())).isInstanceOf(DomainFailure.class).hasMessageContaining("occupied");assertThat(buses.trip(page.id(),trip.id(),true).trip().seats()).anyMatch(s->s.id().equals("L6")&&s.status()==Bus.SeatStatus.OCCUPIED);assertThat(buses.search(new Bus.Criteria(Bus.City.DELHI,Bus.City.PUNE,future(),List.of(30))).total()).isZero();assertThatThrownBy(()->buses.search(new Bus.Criteria(Bus.City.GOA,Bus.City.DELHI,future(),List.of(30)))).isInstanceOf(DomainFailure.class).hasMessageContaining("unavailable");}
 Cab.Criteria cab(Cab.Type type){return new Cab.Criteria(type,type==Cab.Type.AIRPORT?Cab.Place.DELHI_AIRPORT:Cab.Place.DELHI_CENTRE,type==Cab.Type.LOCAL||type==Cab.Type.AIRPORT?Cab.Place.DELHI_CENTRE:Cab.Place.JAIPUR_CENTRE,future(),"10:00",type==Cab.Type.OUTSTATION_ROUND_TRIP?future().plusDays(1):null,type==Cab.Type.OUTSTATION_ROUND_TRIP?"18:00":null,5,4,type==Cab.Type.LOCAL?8:0);}
 @Test void cabModesCapacityRepriceAndExtrasStayExplicit(){for(var type:Cab.Type.values()){var page=cabs.search(cab(type));assertThat(page.items()).hasSize(2).allMatch(o->o.category()==Cab.Category.SUV);var offer=page.items().getFirst();assertThat(offer.exclusions()).anyMatch(v->v.contains("Tolls"));var fresh=cabs.reprice(page.id(),offer.id());assertThat(fresh.changed()).isTrue();assertThat(fresh.offer().total().decimal()).isEqualByComparingTo(offer.total().decimal().add(new BigDecimal("110")));assertThat(fresh.offer().baseFare().decimal().add(fresh.offer().taxes().decimal()).add(fresh.offer().fees().decimal())).isEqualByComparingTo(fresh.offer().total().decimal());if(type==Cab.Type.OUTSTATION_ROUND_TRIP)assertThat(offer.includedKm()).isEqualTo(540);if(type==Cab.Type.LOCAL)assertThat(offer.includedKm()).isEqualTo(80);}}
 @Test void cabInvalidRoutesSchedulesOwnershipOfSearchAndExpiryFailSafely()throws Exception{assertThatThrownBy(()->new Cab.Criteria(Cab.Type.AIRPORT,Cab.Place.DELHI_AIRPORT,Cab.Place.MUMBAI_CENTRE,future(),"10:00",null,null,2,1,0)).isInstanceOf(DomainFailure.class);var shortRound=new Cab.Criteria(Cab.Type.OUTSTATION_ROUND_TRIP,Cab.Place.DELHI_CENTRE,Cab.Place.JAIPUR_CENTRE,future(),"10:00",future(),"13:00",2,1,0);assertThat(call("POST","/api/v1/cabs/search",null,null,shortRound).statusCode()).isEqualTo(422);var page=cabs.search(cab(Cab.Type.AIRPORT));assertThatThrownBy(()->cabs.detail(UUID.randomUUID(),page.items().getFirst().id())).isInstanceOf(DomainFailure.class);clock.now=page.expiresAt();assertThatThrownBy(()->cabs.reprice(page.id(),page.items().getFirst().id())).isInstanceOf(DomainFailure.class);}
 Holiday.Quote quote(){var pack=holidays.detail("sample-goa-coast");return holidays.quote(identity,new Holiday.Selection(pack.id(),pack.departures().getFirst(),2,List.of(4,8),Holiday.Upgrade.COMFORT,true),key(),UUID.randomUUID());}
 @Test void holidayCatalogueCustomizationAndOwnedQuotationAreImmutable()throws Exception{var all=holidays.list(new Holiday.Filter("",Holiday.RegionFilter.ALL,Holiday.ThemeFilter.ALL,new BigDecimal("999999"),30,Holiday.Sort.PRICE));assertThat(all.items()).hasSize(3);assertThat(all.items()).anyMatch(p->p.region()==Holiday.Region.INTERNATIONAL);var q=quote();assertThat(q.travelPackage().itinerary().getFirst().hotel()).contains("comfort");assertThat(q.travelPackage().inclusions()).contains("Sample extra activity on day 2");assertThat(q.subtotal().decimal()).isEqualByComparingTo("48000");assertThat(q.total().decimal()).isEqualByComparingTo("53000");assertThat(call("GET","/api/v1/holidays/quotes/"+q.id(),null,null,null).statusCode()).isEqualTo(401);String bob=issuer.token("other-multi","bookings:read bookings:write");assertThat(call("GET","/api/v1/holidays/quotes/"+q.id(),bob,null,null).statusCode()).isEqualTo(404);assertThat(call("GET","/api/v1/holidays/quotes/"+q.id(),token,null,null).statusCode()).isEqualTo(200);assertThatThrownBy(()->jdbc.sql("update holiday_quote set payload='{}' where id=:id").param("id",q.id()).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void holidayEnquiryIsConcurrentIdempotentOwnedAndNotAReservation()throws Exception{var q=quote();var contact=new Holiday.Contact("Alex Example","alex@example.test","Fictional local enquiry");String key=key();List<Holiday.Enquiry> results;try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<Holiday.Enquiry>>of(()->holidays.enquire(identity,q.id(),contact,true,key,UUID.randomUUID()),()->holidays.enquire(identity,q.id(),contact,true,key,UUID.randomUUID())));results=List.of(calls.get(0).get(),calls.get(1).get());}assertThat(results.getFirst().id()).isEqualTo(results.getLast().id());assertThat(results.getFirst().status()).isEqualTo("RECORDED_LOCALLY");assertThat(holidays.enquiryForQuote(identity,q.id())).isEqualTo(results.getFirst().id());assertThat(jdbc.sql("select count(*) from holiday_enquiry where quote_id=:id").param("id",q.id()).query(Integer.class).single()).isEqualTo(1);assertThatThrownBy(()->holidays.enquire(identity,q.id(),new Holiday.Contact("Alex Example","alex@example.test","changed"),true,key,UUID.randomUUID())).isInstanceOf(DomainFailure.class).hasMessageContaining("different");String bob=issuer.token("enquiry-other","bookings:read");assertThat(call("GET","/api/v1/holidays/enquiries/"+results.getFirst().id(),bob,null,null).statusCode()).isEqualTo(404);assertThat(jdbc.sql("select count(*) from payment_account").query(Integer.class).single()).isZero();}
 @Test void holidayExpiryPolicyAndTransactionFailureDoNotCreatePhantomEnquiries(){var q=quote();clock.now=q.expiresAt();assertThatThrownBy(()->holidays.enquire(identity,q.id(),new Holiday.Contact("Alex","a@example.test",""),true,key(),UUID.randomUUID())).isInstanceOf(DomainFailure.class).hasMessageContaining("expired");clock.now=Instant.now();var direct=holidays.detail("sample-jaipur-culture");assertThatThrownBy(()->holidays.quote(identity,new Holiday.Selection(direct.id(),direct.departures().getFirst(),1,List.of(),Holiday.Upgrade.COMFORT,false),key(),UUID.randomUUID())).isInstanceOf(DomainFailure.class);var valid=quote();jdbc.sql("create function holiday_event_failure() returns trigger language plpgsql as $$ begin raise exception 'Injected event failure'; end $$").update();jdbc.sql("create trigger holiday_event_failure before insert on holiday_outbox for each row execute function holiday_event_failure()").update();try{assertThatThrownBy(()->holidays.enquire(identity,valid.id(),new Holiday.Contact("Alex","a@example.test",""),true,key(),UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(holidays.enquiryForQuote(identity,valid.id())).isNull();}finally{jdbc.sql("drop trigger holiday_event_failure on holiday_outbox").update();jdbc.sql("drop function holiday_event_failure()").update();}}

 @Test void holidayAndCabPartialOutagesNeverBecomeFalseZeroAvailability(){var partial=holidays.list(new Holiday.Filter("Goa",Holiday.RegionFilter.ALL,Holiday.ThemeFilter.ALL,new BigDecimal("999999"),30,Holiday.Sort.PRICE));assertThat(partial.items()).hasSize(1);assertThat(partial.coverage()).anyMatch(c->c.status()==SupplierCoverage.Status.UNAVAILABLE);assertThatThrownBy(()->holidays.list(new Holiday.Filter("Shimla",Holiday.RegionFilter.ALL,Holiday.ThemeFilter.ALL,new BigDecimal("999999"),30,Holiday.Sort.PRICE))).isInstanceOf(DomainFailure.class).hasMessageContaining("unavailable");assertThat(holidays.list(new Holiday.Filter("Unknown",Holiday.RegionFilter.ALL,Holiday.ThemeFilter.ALL,new BigDecimal("999999"),30,Holiday.Sort.PRICE)).total()).isZero();var c=cabs.search(new Cab.Criteria(Cab.Type.AIRPORT,Cab.Place.GOA_AIRPORT,Cab.Place.GOA_CENTRE,future(),"10:00",null,null,2,1,0));assertThat(c.items()).hasSize(3);assertThat(c.coverage()).anyMatch(v->v.status()==SupplierCoverage.Status.UNAVAILABLE);assertThatThrownBy(()->cabs.search(new Cab.Criteria(Cab.Type.OUTSTATION_ONE_WAY,Cab.Place.JAIPUR_CENTRE,Cab.Place.DELHI_CENTRE,future(),"10:00",null,null,2,1,0))).isInstanceOf(DomainFailure.class).hasMessageContaining("unavailable");}
 @Test void cabObservationExpiresAtSchedulingCutoff(){clock.now=Instant.parse("2026-11-02T10:00:00Z");var pickup=clock.now.plusSeconds(7260).atZone(ZoneId.of("Asia/Kolkata"));var page=cabs.search(new Cab.Criteria(Cab.Type.AIRPORT,Cab.Place.DELHI_AIRPORT,Cab.Place.DELHI_CENTRE,pickup.toLocalDate(),pickup.toLocalTime().toString(),null,null,2,1,0));assertThat(page.expiresAt()).isEqualTo(clock.now.plusSeconds(60));clock.now=page.expiresAt();assertThatThrownBy(()->cabs.detail(page.id(),page.items().getFirst().id())).isInstanceOf(DomainFailure.class).hasMessageContaining("expired");}
 @Test void supplierFanoutIsBoundedAndDeadlineFailuresKeepCoverage(){var pool=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(1),new ThreadPoolExecutor.AbortPolicy());try{var calls=new com.travbook.shared.adapter.out.supplier.BoundedDiscovery(pool,new io.micrometer.core.instrument.simple.SimpleMeterRegistry(),60);long start=System.nanoTime();var result=calls.collect("test",List.of("one","two","three"),id->{try{Thread.sleep(5000);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Cancelled");}return List.of(id);});assertThat(result.items()).isEmpty();assertThat(result.coverage()).hasSize(3).allMatch(v->v.status()==SupplierCoverage.Status.UNAVAILABLE);assertThat(Duration.ofNanos(System.nanoTime()-start)).isLessThan(Duration.ofSeconds(2));assertThat(pool.getLargestPoolSize()).isEqualTo(1);}finally{pool.shutdownNow();}}
}
